INSERT INTO step4.four_tuples (id,analysis_id,associated_causal_factor,code,rationale,recommendation,scenario) VALUES
	 ('1189a412-10bc-4321-85c1-56f0e57ab6ab','3560faf9-eed1-4708-a22d-d50eebfe6b26','Lack of essential input data.','LC-5','Both credentials are required to ensure secure user identification.','Require both username and password to complete authentication.','Incomplete authentication, as the user did not provide a username, only a password.'),
	 ('2cb79d58-1120-40e7-b1f5-435eeb0d9cfc','3560faf9-eed1-4708-a22d-d50eebfe6b26','Malicious action in an attempt to bypass authentication. Such as using the SQL injection attack technique.','LC-6','Protects against malicious attempts to manipulate the authentication process.','Strengthen security measures, such as implementing more rigorous checks and monitoring for suspicious patterns.','Malicious manipulation, as an actor attempts to exploit a potential vulnerability by providing only the password, without including the username.'),
	 ('3a0e1387-c268-4335-acfd-582fbc81b7d8','3560faf9-eed1-4708-a22d-d50eebfe6b26','Usability issue in the registry interface.','LC-2','This recommendation aims to improve usability by making it easier for the user to find and enter the password during registration.','Improve the interface, ensuring that fields are clearly identified and providing an intuitive user experience.','Confusing interface during registration, the user finds it difficult to interact with the registration interface.'),
	 ('75a6f203-5f2c-41ce-84a0-caa14ed7e936','3560faf9-eed1-4708-a22d-d50eebfe6b26','There''s a technical issue with the form validation process, which could be attributed to several factors, including a button that isn''t working properly, an invalid destination URL, or a backend issue resulting in an Internal Server Error.','LC-3','This recommendation ensures that the system works correctly, avoiding user frustration caused by technical failures in form validation.','Perform regular system testing and implement contingency plans to quickly resolve technical issues.','Technical problem in form validation, as the user correctly fills in the username and password (control action issued correctly), but for some reason it was not executed or followed properly.'),
	 ('bca22bab-72c5-4eef-8d07-53de22fd9c85','3560faf9-eed1-4708-a22d-d50eebfe6b26','Technical problem with automatic interface update.','LC-1','Ensures that the interface is reliable, minimizing technical errors that could cause confusion to the user.','Perform regular testing to ensure the interface automatically refreshes after initial credential entry, avoiding confusion.','The automatic update of the field failed because the user did not realize that, even after entering the username and password, the data was not incorporated into the form.'),
	 ('d99a6b3a-09a5-42b3-b8dc-7e9b62305838','3560faf9-eed1-4708-a22d-d50eebfe6b26','Security policy that locks accounts after multiple failed attempts.','LC-4','Improves security while maintaining transparency about temporary account locks.','Implement more flexible account lockout policies and notify users of lockouts to avoid confusion.','The user''s account is temporarily locked due to previous failed login attempts. This prevents access even when a valid username and password are provided.');
